// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/me", wrapper.GetCurrentAdmin)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tunnels", wrapper.ListTunnels)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/tunnels", wrapper.CreateTunnel)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/tunnels/{tunnel_id}", wrapper.DeleteTunnel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tunnels/{tunnel_id}", wrapper.GetTunnel)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/tunnels/{tunnel_id}", wrapper.UpdateTunnel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tunnels/{tunnel_id}/connectors", wrapper.ListTunnelConnectors)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tunnels/{tunnel_id}/token", wrapper.RevealTunnelToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/tunnels/{tunnel_id}/token/rotate", wrapper.RotateTunnelToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/tunnels/{tunnel_id}/token/revoke", wrapper.RevokeTunnelToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/tunnels/{tunnel_id}/revoke", wrapper.RevokeTunnel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/services", wrapper.ListServices)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/services", wrapper.CreateService)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/services/{service_id}", wrapper.DeleteService)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/services/{service_id}", wrapper.GetService)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/services/{service_id}", wrapper.UpdateService)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/services/{service_id}/enable", wrapper.EnableService)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/services/{service_id}/disable", wrapper.DisableService)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/dashboard", wrapper.GetDashboard)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/system/info", wrapper.GetSystemInfo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/system/health", wrapper.GetSystemHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/system/config", wrapper.GetSystemConfig)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/security-audit-events", wrapper.ListSecurityAuditEvents)

	return m
}

