// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login 创建管理员 Session
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout 销毁当前管理员 Session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetCurrentAdmin 读取当前管理员和 CSRF Token
	// (GET /auth/me)
	GetCurrentAdmin(ctx context.Context, request GetCurrentAdminRequestObject) (GetCurrentAdminResponseObject, error)
	// GetDashboard 读取 Server 权威状态汇总
	// (GET /dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// ListSecurityAuditEvents 只读查询持久化 Security Audit Event
	// (GET /security-audit-events)
	ListSecurityAuditEvents(ctx context.Context, request ListSecurityAuditEventsRequestObject) (ListSecurityAuditEventsResponseObject, error)
	// ListServices 分页读取一个 Tunnel 下的 Service
	// (GET /services)
	ListServices(ctx context.Context, request ListServicesRequestObject) (ListServicesResponseObject, error)
	// CreateService 在指定 Tunnel 下创建 Service
	// (POST /services)
	CreateService(ctx context.Context, request CreateServiceRequestObject) (CreateServiceResponseObject, error)
	// DeleteService 删除 Service 及其唯一 Public Exposure
	// (DELETE /services/{service_id})
	DeleteService(ctx context.Context, request DeleteServiceRequestObject) (DeleteServiceResponseObject, error)
	// GetService 读取单个 Service
	// (GET /services/{service_id})
	GetService(ctx context.Context, request GetServiceRequestObject) (GetServiceResponseObject, error)
	// UpdateService 以 JSON Merge Patch 修改 Service
	// (PATCH /services/{service_id})
	UpdateService(ctx context.Context, request UpdateServiceRequestObject) (UpdateServiceResponseObject, error)
	// DisableService 禁用 Service
	// (POST /services/{service_id}/disable)
	DisableService(ctx context.Context, request DisableServiceRequestObject) (DisableServiceResponseObject, error)
	// EnableService 启用 Service
	// (POST /services/{service_id}/enable)
	EnableService(ctx context.Context, request EnableServiceRequestObject) (EnableServiceResponseObject, error)
	// GetSystemConfig 读取安全的 Server 有效配置投影
	// (GET /system/config)
	GetSystemConfig(ctx context.Context, request GetSystemConfigRequestObject) (GetSystemConfigResponseObject, error)
	// GetSystemHealth 读取已认证的管理面健康状态
	// (GET /system/health)
	GetSystemHealth(ctx context.Context, request GetSystemHealthRequestObject) (GetSystemHealthResponseObject, error)
	// GetSystemInfo 读取 Server 构建与运行信息
	// (GET /system/info)
	GetSystemInfo(ctx context.Context, request GetSystemInfoRequestObject) (GetSystemInfoResponseObject, error)
	// ListTunnels 分页读取 Tunnel
	// (GET /tunnels)
	ListTunnels(ctx context.Context, request ListTunnelsRequestObject) (ListTunnelsResponseObject, error)
	// CreateTunnel 创建 Tunnel 并签发第一代 Connection Token
	// (POST /tunnels)
	CreateTunnel(ctx context.Context, request CreateTunnelRequestObject) (CreateTunnelResponseObject, error)
	// DeleteTunnel 删除没有 Service 引用的 Tunnel
	// (DELETE /tunnels/{tunnel_id})
	DeleteTunnel(ctx context.Context, request DeleteTunnelRequestObject) (DeleteTunnelResponseObject, error)
	// GetTunnel 读取单个 Tunnel
	// (GET /tunnels/{tunnel_id})
	GetTunnel(ctx context.Context, request GetTunnelRequestObject) (GetTunnelResponseObject, error)
	// UpdateTunnel 以 JSON Merge Patch 修改 Tunnel 名称
	// (PATCH /tunnels/{tunnel_id})
	UpdateTunnel(ctx context.Context, request UpdateTunnelRequestObject) (UpdateTunnelResponseObject, error)
	// ListTunnelConnectors 分页读取仍有 Current Control Session 的 Connector
	// (GET /tunnels/{tunnel_id}/connectors)
	ListTunnelConnectors(ctx context.Context, request ListTunnelConnectorsRequestObject) (ListTunnelConnectorsResponseObject, error)
	// RevokeTunnel 撤销 Tunnel、全部 Token 与运行时访问
	// (POST /tunnels/{tunnel_id}/revoke)
	RevokeTunnel(ctx context.Context, request RevokeTunnelRequestObject) (RevokeTunnelResponseObject, error)
	// RevealTunnelToken 审计后返回当前 ACTIVE Connection Token
	// (GET /tunnels/{tunnel_id}/token)
	RevealTunnelToken(ctx context.Context, request RevealTunnelTokenRequestObject) (RevealTunnelTokenResponseObject, error)
	// RevokeTunnelToken 撤销当前 Token 的新认证但不撤销 Tunnel
	// (POST /tunnels/{tunnel_id}/token/revoke)
	RevokeTunnelToken(ctx context.Context, request RevokeTunnelTokenRequestObject) (RevokeTunnelTokenResponseObject, error)
	// RotateTunnelToken 签发下一代 Token；既有 Session 保持在线
	// (POST /tunnels/{tunnel_id}/token/rotate)
	RotateTunnelToken(ctx context.Context, request RotateTunnelTokenRequestObject) (RotateTunnelTokenResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

